  if ((value.nextId as number) <= maximumId) {
    fail("malformed database: nextId does not exceed existing ids");
  }
  return { version: 1, nextId: value.nextId as number, tasks };
}

function saveDatabase(database: Database): void {
  const directory = dirname(databasePath);
  const temporary = join(
    directory,
    `.${databasePath.split(/[\\/]/).pop()}.${process.pid}.${crypto.randomUUID()}.tmp`,
  );
  try {
    writeFileSync(temporary, `${JSON.stringify(database, null, 2)}\n`, { flag: "wx" });
    renameSync(temporary, databasePath);
  } catch (error) {
    try {
      unlinkSync(temporary);
    } catch {}
    fail(`cannot write database: ${(error as Error).message}`);
  }
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function normalizeTags(input: string): string[] {
  const result: string[] = [];
  const seen = new Set<string>();
  for (const part of input.split(",")) {
    const tag = normalizeTag(part);
    if (tag && !seen.has(tag)) {
      seen.add(tag);
      result.push(tag);
    }
  }
  return result;
}

function parseFlags(args: string[], allowed: ReadonlySet<string>): Map<string, string> {
  const result = new Map<string, string>();
  for (let i = 0; i < args.length; i += 2) {
    const flag = args[i];
    if (!flag?.startsWith("--")) fail(`unexpected argument: ${flag ?? ""}`);
    if (!allowed.has(flag)) fail(`unknown flag: ${flag}`);
    if (result.has(flag)) fail(`duplicate flag: ${flag}`);
    const value = args[i + 1];
    if (value === undefined || value.startsWith("--")) fail(`missing value for ${flag}`);
    result.set(flag, value);
  }
  return result;
}

function parseId(value: string | undefined): number {
  if (!value || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a safe positive integer");
  return id;
}

function requireTask(database: Database, id: number): Task {
  const task = database.tasks.find((candidate) => candidate.id === id);
  if (!task) fail(`task ${id} not found`);
  return task;
}

function localToday(): string {
  const now = new Date();
  const year = String(now.getFullYear()).padStart(4, "0");
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function execute(args: string[]): unknown {
  const [command, ...rest] = args;
  if (!command) fail("missing command");

  if (command === "add") {
    const flags = parseFlags(rest, new Set(["--title", "--tags", "--due"]));
    const title = flags.get("--title");
    if (title === undefined) fail("missing required flag: --title");
    if (title.trim() === "") fail("title must not be empty");
    const due = flags.get("--due");
    if (due !== undefined && !validDate(due)) fail("due date must be a valid YYYY-MM-DD date");
    const database = loadDatabase();
    const task: Task = {
      id: database.nextId,
      title,
      status: "open",
      createdAt: new Date().toISOString(),
      tags: normalizeTags(flags.get("--tags") ?? ""),
      ...(due === undefined ? {} : { due }),
    };
    database.nextId += 1;
    database.tasks.push(task);
    saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(rest, new Set(["--status", "--tag", "--overdue"]));
    const status = flags.get("--status");
    if (status !== undefined && status !== "open" && status !== "done") {
      fail("status must be open or done");
    }
    const overdue = flags.get("--overdue");
    if (overdue !== undefined && !validDate(overdue)) {
      fail("overdue date must be a valid YYYY-MM-DD date");
    }
    const requestedTag = flags.has("--tag") ? normalizeTag(flags.get("--tag")!) : undefined;
    if (requestedTag === "") fail("tag must not be empty");
    return loadDatabase().tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => requestedTag === undefined || task.tags.includes(requestedTag))
      .filter(
        (task) =>
          overdue === undefined ||
          (task.status === "open" && task.due !== undefined && task.due < overdue),
      )
      .sort((a, b) => a.id - b.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail("usage: done ID");
    const id = parseId(rest[0]);
    const database = loadDatabase();
    const task = requireTask(database, id);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail("usage: delete ID");
    const id = parseId(rest[0]);
    const database = loadDatabase();
    const task = requireTask(database, id);
    database.tasks = database.tasks.filter((candidate) => candidate.id !== id);
    saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (rest.length !== 0) fail("stats does not accept arguments");
    const tasks = loadDatabase().tasks;
    const today = localToday();
    const open = tasks.filter((task) => task.status === "open").length;
    return {
      total: tasks.length,
      open,
      done: tasks.length - open,
      overdue: tasks.filter(
        (task) => task.status === "open" && task.due !== undefined && task.due < today,
      ).length,
    };
import { afterEach, describe, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const project = join(import.meta.dir, "..");
const directories: string[] = [];

function temporaryDatabase(): string {
  const directory = mkdtempSync(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return join(directory, "tasks.json");
}

function run(database: string, ...args: string[]) {
  const result = Bun.spawnSync(["bun", "run", "src/cli.ts", ...args], {
    cwd: project,
    env: { ...process.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  const stdout = result.stdout.toString().trim();
  return {
    exitCode: result.exitCode,
    stdout,
    stderr: result.stderr.toString().trim(),
    json: JSON.parse(stdout),
  };
}

afterEach(() => {
  for (const directory of directories.splice(0)) rmSync(directory, { recursive: true });
});

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, filters, and keeps ids monotonic", () => {
    const database = temporaryDatabase();
    const first = run(database, "add", "--title", "Write tests", "--tags", " Work,work, CLI ", "--due", "2020-01-01");
    expect(first.exitCode).toBe(0);
    expect(first.json).toMatchObject({ id: 1, status: "open", tags: ["work", "cli"], due: "2020-01-01" });
    expect(run(database, "add", "--title", "Ship", "--tags", "release").json.id).toBe(2);
    expect(run(database, "list", "--status", "open", "--tag", "WORK").json.map((task: { id: number }) => task.id)).toEqual([1]);
    expect(run(database, "list", "--overdue", "2020-01-02").json.map((task: { id: number }) => task.id)).toEqual([1]);

    const done = run(database, "done", "1");
    expect(done.json.status).toBe("done");
    const completedAt = done.json.completedAt;
    expect(run(database, "done", "1").json.completedAt).toBe(completedAt);
    expect(run(database, "stats").json).toEqual({ total: 2, open: 1, done: 1, overdue: 0 });
    expect(run(database, "delete", "2").json.id).toBe(2);
    expect(run(database, "add", "--title", "Next").json.id).toBe(3);
  });

  test("rejects invalid input with one JSON stdout value and preserves malformed data", () => {
    const database = temporaryDatabase();
    const badDate = run(database, "add", "--title", "Bad", "--due", "2023-02-29");
    expect(badDate.exitCode).not.toBe(0);
    expect(badDate.json.error).toContain("valid YYYY-MM-DD");
    expect(badDate.stderr).not.toBe("");

    writeFileSync(database, "not json\n");
    const malformed = run(database, "add", "--title", "Must not overwrite");
    expect(malformed.exitCode).not.toBe(0);
    expect(malformed.json.error).toContain("malformed database");
    expect(readFileSync(database, "utf8")).toBe("not json\n");
  });

  test("rejects unknown flags, missing tasks, and invalid commands", () => {
    const database = temporaryDatabase();
    for (const args of [
      ["add", "--title", "A", "--wat", "x"],
      ["done", "99"],
      ["nonsense"],
    ]) {
      const result = run(database, ...args);
      expect(result.exitCode).not.toBe(0);
      expect(typeof result.json.error).toBe("string");
    }
  });
});
# Taskboard CLI

A dependency-free TypeScript task manager for [Bun](https://bun.sh/). Tasks are stored in `.taskboard.json` in the current directory, or at `TASKBOARD_FILE` when that environment variable is set. Database updates use a sibling temporary file and an atomic rename.

```sh
bun run src/cli.ts add --title "Write release notes" --tags docs,release --due 2026-09-10
bun run src/cli.ts list --status open --tag docs
bun run src/cli.ts list --overdue 2026-09-11
bun run src/cli.ts done 1
bun run src/cli.ts delete 1
bun run src/cli.ts stats
```

Every command writes exactly one JSON value to stdout. Errors also write a diagnostic to stderr and exit non-zero. Tags are trimmed, lowercased, and deduplicated. List filters combine with AND; overdue filtering includes only open tasks due strictly before the supplied date.

Run the self-tests with:

```sh
bun test
